<script setup>
import { useI18n } from "../../lib/i18n.js";
import LanguageSwitch from "../../Components/LanguageSwitch.vue";
const {t,locale}=useI18n();
import { Head, useForm } from '@inertiajs/vue3';
import AppLayout from '../../Layouts/AppLayout.vue';
import Errors from '../../Components/Errors.vue';
defineProps({preview:{type:Object,default:null},collections:{type:Array,default:()=>[]}});
const form=useForm({file:null,term_column:0,definition_column:1,has_header:true});
const save=useForm({collection_id:''});
const upload=()=>form.post('/imports/preview',{forceFormData:true});
</script>
<template><Head :title="t('Import words')"/><AppLayout :title="t('Bring your words along.')" :subtitle="t('From a spreadsheet to your next study session.')"><div class="import-grid"><section class="panel"><span class="step-label">{{t("01 / UPLOAD & MAP")}}</span><h2>{{t("A CSV full of possibilities.")}}</h2><p class="muted">{{t("Choose a UTF-8 CSV with a word column and a definition column. Preview everything before importing.")}}</p><form @submit.prevent="upload"><Errors :errors="form.errors"/><label class="upload-zone"><span class="upload-icon">↥</span><strong>{{form.file?.name || t('Choose a CSV file')}}</strong><small>{{t("Up to 2 MB · .csv or .txt")}}</small><input type="file" accept=".csv,.txt,text/csv,text/plain" @change="form.file=$event.target.files[0]" required/></label><div class="two-col"><label>{{t("Word column")}}<select v-model.number="form.term_column"><option v-for="n in 20" :key="n" :value="n-1">{{t('Column')}} {{n}}</option></select></label><label>{{t("Definition column")}}<select v-model.number="form.definition_column"><option v-for="n in 20" :key="n" :value="n-1">{{t('Column')}} {{n}}</option></select></label></div><label class="check"><input type="checkbox" v-model="form.has_header"/> {{t("First row contains column headings")}}</label><div class="form-actions"><button class="button" :disabled="form.processing">{{form.processing?t('Reading file…'):t('Preview import →')}}</button></div></form></section><aside class="import-help"><span class="eyebrow">{{t("A SIMPLE START")}}</span><h3>{{t("Two columns.")}}<br>{{t("A whole new collection.")}}</h3><pre>term,definition
curious,eager to learn
resilient,able to recover</pre><p>{{t("Your original words and definitions stay as they are. Add your own translations as private notes later.")}}</p><p>{{t("Exact duplicates in your word pool are skipped, not overwritten.")}}</p></aside></div><section v-if="preview" class="panel preview"><span class="step-label">{{t("02 / REVIEW & IMPORT")}}</span><div class="section-heading"><h2>{{t("Looking good?")}}</h2><span class="pill dark">{{preview.total}} {{t('rows')}} · {{preview.duplicates??0}} {{t('duplicates')}}</span></div><p v-if="preview.headers?.length" class="muted small">{{t('Columns:')}} {{preview.headers.join(' · ')}}</p><div class="preview-table"><table><thead><tr><th>{{t("Word")}}</th><th>{{t("Definition")}}</th></tr></thead><tbody><tr v-for="(row,index) in preview.rows" :key="index"><td>{{row.term}}</td><td>{{row.definition}}</td></tr></tbody></table></div><p class="muted small">{{t('Preview may show only the first rows. The validated import contains {count} rows.',{count:preview.total})}}</p><form @submit.prevent="save.post('/imports/store')"><Errors :errors="save.errors"/><label v-if="collections.length">{{t("Also add to a collection")}}<select v-model="save.collection_id"><option value="">{{t("Word pool only")}}</option><option v-for="c in collections" :key="c.id" :value="c.id">{{c.title}}</option></select></label><div class="form-actions"><button class="button" :disabled="save.processing">{{save.processing?t('Importing…'):t('Import into my pool')}}</button></div></form></section></AppLayout></template>
